/*
  Preloader : écran de chargement décoratif (faux chargement de ~3 secondes).

  Ce que ça fait, dans l'ordre :
    1. Le logo apparaît, la barre se remplit de 0 à 100 % (le texte change en cours de route)
    2. Une courte pause sur « Prêt »
    3. Le contenu s'efface et l'écran se « dissout » en un cercle qui s'agrandit, flou sur les bords
    4. L'écran est retiré de la page

  C'est un faux chargement : il n'attend rien du tout, la durée est toujours la même.
  Il se joue à chaque ouverture de la page, même avec un refresh.

  Il utilise GSAP, comme tes autres composants.

  Attributs data-* (tous optionnels) sur .preloader :
    data-duration       durée totale en secondes                  (3)
    data-text-load      texte au début                            (Chargement du site web en cours)
    data-text-shaders   texte à partir de 55 %                    (Compilation des shaders)
    data-text-done      texte à 100 %                             (Prêt)

  Événements envoyés sur window (TextAnim s'en sert pour attendre la fin du loader) :
    preloader:done      au début du dissolve
    preloader:complete  quand le loader est retiré de la page
*/

import gsap from 'gsap';

export default class Preloader {
  constructor(element) {
    this.el = element;
    this.root = document.documentElement;

    const d = element.dataset;
    const total = parseFloat(d.duration) || 3;
    this.pause = 0.25; // pause sur « Prêt »
    this.dissolveTime = 0.9; // durée du dissolve
    this.barTime = Math.max(0.8, total - this.pause - this.dissolveTime);

    this.texts = {
      load: d.textLoad || 'Chargement du site web en cours',
      shaders: d.textShaders || 'Compilation des shaders',
      done: d.textDone || 'Prêt',
    };
    this.reduced = window.matchMedia(
      '(prefers-reduced-motion: reduce)',
    ).matches;

    // Les éléments qu'on va animer
    this.content = element.querySelector('.preloader__content');
    this.glow = element.querySelector('.preloader__glow');
    this.fill = element.querySelector('.preloader__fill');
    this.bar = element.querySelector('.preloader__bar');
    this.status = element.querySelector('.preloader__status');
    this.percent = element.querySelector('.preloader__percent');

    this.root.classList.add('is-loading'); // (déjà mis dans le HTML, au cas où)
    element.classList.add('is-active'); // arrête l'animation d'attente du CSS
    this.lockScroll();
    this.render(0);
    this.start();
  }

  // 1) La barre qui se remplit
  start() {
    const progress = { value: 0 };

    gsap.to(progress, {
      value: 1,
      duration: this.barTime,
      ease: 'power2.inOut', // démarre doucement, accélère, finit doucement
      onUpdate: () => this.render(progress.value),
      onComplete: () => gsap.delayedCall(this.pause, () => this.dissolve()),
    });
  }

  // Met à jour la barre, le pourcentage et le texte
  render(v) {
    const pct = Math.round(v * 100);
    this.fill.style.transform = `scaleX(${v})`;
    this.percent.textContent = `${pct}%`;
    this.bar.setAttribute('aria-valuenow', String(pct));

    const text =
      v >= 1
        ? this.texts.done
        : v >= 0.55
          ? this.texts.shaders
          : this.texts.load;
    if (this.status.textContent !== text) this.status.textContent = text;
  }

  // 2) La fin : le contenu s'efface, puis le cercle de dissolve s'agrandit
  dissolve() {
    // On prévient le reste du site : TextAnim et cie peuvent démarrer
    this.root.classList.add('preloader-done');
    window.dispatchEvent(new Event('preloader:done'));

    // Reduced motion : simple fondu, sans animation de cercle
    if (this.reduced) {
      gsap.to(this.el, {
        opacity: 0,
        duration: 0.3,
        onComplete: () => this.cleanup(),
      });
      return;
    }

    gsap.to(this.content, {
      opacity: 0,
      y: -10,
      scale: 1.05,
      filter: 'blur(8px)',
      duration: 0.45,
      ease: 'power2.inOut',
    });
    gsap.to(this.glow, { opacity: 0, duration: 0.6 });

    // --reveal est une variable CSS lue par le mask-image du SCSS (classe .is-dissolving).
    // On la fait passer de -25 (tout est caché) à 100 (le trou couvre tout l'écran).
    this.el.classList.add('is-dissolving');
    const hole = { reveal: -25 };
    gsap.to(hole, {
      reveal: 100,
      duration: this.dissolveTime,
      ease: 'power2.inOut',
      onUpdate: () => this.el.style.setProperty('--reveal', hole.reveal),
      onComplete: () => this.cleanup(),
    });
  }

  // 3) On retire tout
  cleanup() {
    this.unlockScroll();
    this.root.classList.remove('is-loading');
    this.root.classList.add('is-loaded');
    this.el.remove();
    window.dispatchEvent(new Event('preloader:complete'));
  }

  // Empêche de scroller pendant le chargement (sans toucher au CSS de la page)
  lockScroll() {
    this.block = (e) => e.preventDefault();
    this.blockKeys = (e) => {
      if (
        [
          ' ',
          'PageUp',
          'PageDown',
          'Home',
          'End',
          'ArrowUp',
          'ArrowDown',
        ].includes(e.key)
      )
        e.preventDefault();
    };
    window.addEventListener('wheel', this.block, { passive: false });
    window.addEventListener('touchmove', this.block, { passive: false });
    window.addEventListener('keydown', this.blockKeys);
  }

  unlockScroll() {
    window.removeEventListener('wheel', this.block);
    window.removeEventListener('touchmove', this.block);
    window.removeEventListener('keydown', this.blockKeys);
  }

  destroy() {
    gsap.killTweensOf([this.el, this.content, this.glow]);
    this.unlockScroll();
  }
}
