/*
  TrueFocus : port vanilla du composant React Bits (sans la librairie « motion »).
  Un cadre (crochets, boîte, soulignement ou surlignage) se déplace d'un mot à l'autre
  pendant que le reste du texte est flou.

  Utilisation :
    <h3 data-component="TrueFocus">Créateur de média 3D<br />Designer UI/UX</h3>

  Découpage : s'il y a des <br>, chaque ligne est un « mot » du focus. Sinon, chaque mot.
  Pour forcer : data-split="lines" ou data-split="words".

  Attributs data-* (tous optionnels) :
    data-split              lines | words                       (auto)
    data-separator          séparateur des mots                 (espace)
    data-focus-style        brackets | box | underline | highlight   (brackets)
    data-border-color       couleur du cadre                    (#A855F7)
    data-highlight-color    couleur du surlignage               (couleur du cadre)
    data-glow-color         halo autour du cadre                (rgba(168,85,247,.85))
    data-focus-scale        agrandit le mot actif, ex. 1.06     (1)
    data-blur-amount        flou des mots inactifs, en px       (5)
    data-unfocused-opacity  opacité des mots inactifs, 0 à 1    (1)
    data-easing             smooth | spring                     (smooth)
    data-order              sequential | random                 (sequential)
    data-manual             true : le focus suit la souris      (false)
    data-duration           durée du déplacement, en s          (0.5)
    data-pause              pause sur chaque mot, en s          (3)
    data-corner-size        taille des crochets, en px          (14)
    data-border-width       épaisseur du cadre, en px           (3)
    data-gap                espace entre le mot et le cadre, px (8)
*/

const SMOOTH = 'cubic-bezier(0.65, 0, 0.35, 1)';
const SPRING = 'cubic-bezier(0.34, 1.56, 0.64, 1)';
const CORNERS = ['tl', 'tr', 'bl', 'br'];

const num = (v, d) => {
  const n = parseFloat(v);
  return Number.isFinite(n) ? n : d;
};

export default class TrueFocus {
  constructor(element) {
    this.el = element;
    const d = element.dataset;

    this.o = {
      split: d.split === 'lines' || d.split === 'words' ? d.split : null,
      separator: d.separator || ' ',
      style: ['brackets', 'box', 'underline', 'highlight'].includes(
        d.focusStyle,
      )
        ? d.focusStyle
        : 'brackets',
      order: d.order === 'random' ? 'random' : 'sequential',
      easing: d.easing === 'spring' ? 'spring' : 'smooth',
      manual: 'manual' in d && d.manual !== 'false',
      blur: num(d.blurAmount, 5),
      scale: num(d.focusScale, 1),
      unfocused: num(d.unfocusedOpacity, 1),
      duration: num(d.duration, 0.5),
      pause: num(d.pause, 3),
      corner: num(d.cornerSize, 14),
      border: num(d.borderWidth, 3),
      gap: num(d.gap, 8),
      color: d.borderColor || '#A855F7',
      highlight: d.highlightColor || null,
      glow: d.glowColor || 'rgba(168, 85, 247, 0.85)',
    };

    if (window.matchMedia?.('(prefers-reduced-motion: reduce)').matches) {
      this.o.duration = 0;
    }

    this.index = 0;
    this.timer = null;
    this.inView = true;
    this.ready = false;
    this.destroyed = false;

    this.parse();
    if (this.parts.length === 0) return;
    this.build();

    document.fonts.ready.then(() => {
      if (this.destroyed) return;
      this.measureAndStart();
    });
  }

  /* ---------- Lecture du contenu ---------- */

  parse() {
    const html = this.el.innerHTML;
    const hasBr = /<br\s*\/?>/i.test(html);
    this.mode = this.o.split || (hasBr ? 'lines' : 'words');

    const tpl = document.createElement('template'); // inerte : rien ne s'exécute
    const clean = (s) => s.replace(/\s+/g, ' ').trim();

    if (this.mode === 'lines') {
      this.parts = html
        .split(/<br\s*\/?>/i)
        .map((h) => {
          tpl.innerHTML = h;
          return clean(tpl.content.textContent);
        })
        .filter(Boolean);
    } else {
      const text = clean(this.el.textContent);
      const sep = this.o.separator === ' ' ? ' ' : this.o.separator;
      this.parts = text
        .split(sep)
        .map((w) => w.trim())
        .filter(Boolean);
    }
    this.originalHTML = html;
  }

  /* ---------- Construction du DOM ---------- */

  build() {
    const o = this.o;
    const align = getComputedStyle(this.el).textAlign;
    const flexAlign =
      align === 'center'
        ? 'center'
        : align === 'right' || align === 'end'
          ? 'flex-end'
          : 'flex-start';

    // Version lisible par les lecteurs d'écran (le visuel est masqué)
    const sr = document.createElement('span');
    sr.className = 'true-focus__sr';
    sr.textContent = this.parts.join(' ');

    const wrap = document.createElement('span');
    wrap.className = `true-focus true-focus--${this.mode}${o.manual ? ' true-focus--manual' : ''}`;
    wrap.setAttribute('aria-hidden', 'true');
    wrap.style.setProperty('--tf-align', flexAlign);
    wrap.style.setProperty('--tf-gap', `${o.gap}px`);
    wrap.style.setProperty('--tf-color', o.color);
    wrap.style.setProperty('--tf-glow', o.glow);
    wrap.style.setProperty('--tf-corner', `${o.corner}px`);
    wrap.style.setProperty('--tf-border', `${o.border}px`);
    wrap.style.setProperty(
      '--tf-highlight',
      `color-mix(in srgb, ${o.highlight || o.color} 30%, transparent)`,
    );

    this.words = this.parts.map((text, i) => {
      const w = document.createElement('span');
      w.className = 'true-focus__word';
      w.textContent = text;
      if (o.manual) w.addEventListener('mouseenter', () => this.set(i));
      wrap.appendChild(w);
      return w;
    });

    // Le cadre
    const frame = document.createElement('span');
    frame.className = 'true-focus__frame';
    this.parts_el = [];
    if (o.style === 'brackets') {
      CORNERS.forEach((c) =>
        this.addFrameEl(frame, `true-focus__corner true-focus__corner--${c}`),
      );
    } else {
      this.addFrameEl(frame, `true-focus__${o.style}`);
    }
    wrap.appendChild(frame);

    this.el.textContent = '';
    this.el.appendChild(sr);
    this.el.appendChild(wrap);

    this.wrap = wrap;
    this.frame = frame;
    this.updateWords();
  }

  addFrameEl(frame, className) {
    const s = document.createElement('span');
    s.className = className;
    frame.appendChild(s);
    this.parts_el.push(s);
    return s;
  }

  /* ---------- Mesure et démarrage ---------- */

  measureAndStart() {
    this.placeInstant();
    this.ready = true;
    this.wrap.classList.add('is-ready');

    // Replace le cadre si la taille change (rotation du téléphone, redimensionnement, police…)
    this.ro = new ResizeObserver(() => this.placeInstant());
    this.ro.observe(this.wrap);
    this.words.forEach((w) => this.ro.observe(w));

    // Pause hors écran et quand l'onglet est caché
    this.io = new IntersectionObserver((entries) => {
      this.inView = entries[entries.length - 1].isIntersecting;
      this.schedule();
    });
    this.io.observe(this.el);
    this.onVisibility = () => this.schedule();
    document.addEventListener('visibilitychange', this.onVisibility);

    this.schedule();
  }

  /* ---------- Placement du cadre ---------- */

  // Calcule la position du cadre autour du mot actif
  rects() {
    const o = this.o;
    const w = this.words[this.index];
    const s = o.scale;
    const W = w.offsetWidth * s;
    const H = w.offsetHeight * s;
    const x = w.offsetLeft - (w.offsetWidth * (s - 1)) / 2;
    const y = w.offsetTop - (w.offsetHeight * (s - 1)) / 2;
    return { x, y, W, H };
  }

  place() {
    const o = this.o;
    const G = o.gap;
    const { x, y, W, H } = this.rects();
    const t = (el, px, py) =>
      (el.style.transform = `translate3d(${px.toFixed(1)}px, ${py.toFixed(1)}px, 0)`);
    const size = (el, w, h) => {
      el.style.width = `${w.toFixed(1)}px`;
      el.style.height = `${h.toFixed(1)}px`;
    };

    if (o.style === 'brackets') {
      const C = o.corner;
      const pos = {
        tl: [x - G, y - G],
        tr: [x + W + G - C, y - G],
        bl: [x - G, y + H + G - C],
        br: [x + W + G - C, y + H + G - C],
      };
      this.parts_el.forEach((el, i) => t(el, ...pos[CORNERS[i]]));
    } else if (o.style === 'box') {
      const el = this.parts_el[0];
      t(el, x - G, y - G);
      size(el, W + G * 2, H + G * 2);
    } else if (o.style === 'underline') {
      const el = this.parts_el[0];
      t(el, x, y + H + G * 0.4);
      size(el, W, o.border);
    } else {
      const el = this.parts_el[0];
      t(el, x - H * 0.14, y + H * 0.04);
      size(el, W + H * 0.28, H * 0.92);
    }
  }

  // Placement sans animation (premier affichage, redimensionnement)
  placeInstant() {
    this.frame.classList.add('no-anim');
    this.place();
    void this.frame.offsetWidth; // force le recalcul avant de remettre les transitions
    this.frame.classList.remove('no-anim');
  }

  updateWords() {
    const o = this.o;
    const ease = o.easing === 'spring' ? SPRING : SMOOTH;
    const d = o.duration;
    this.frame && this.frame.style.setProperty('--tf-duration', `${d}s`);
    this.frame && this.frame.style.setProperty('--tf-ease', ease);

    this.words.forEach((w, i) => {
      const active = i === this.index;
      w.style.filter = `blur(${active ? 0 : o.blur}px)`;
      w.style.opacity = active ? 1 : o.unfocused;
      w.style.transform = o.scale !== 1 ? `scale(${active ? o.scale : 1})` : '';
      w.style.transition = `filter ${d}s ease, opacity ${d}s ease, transform ${d}s ${ease}`;
    });
  }

  /* ---------- Changement de mot ---------- */

  set(i) {
    if (i === this.index) return;
    this.index = i;
    this.updateWords();
    if (this.ready) this.place();
  }

  next() {
    const n = this.words.length;
    if (this.o.order === 'random') {
      let r = Math.floor(Math.random() * (n - 1));
      if (r >= this.index) r += 1;
      this.set(r);
    } else {
      this.set((this.index + 1) % n);
    }
  }

  schedule() {
    clearTimeout(this.timer);
    if (this.destroyed || this.o.manual || this.words.length < 2) return;
    if (!this.inView || document.hidden) return;
    this.timer = setTimeout(
      () => {
        this.next();
        this.schedule();
      },
      (this.o.duration + this.o.pause) * 1000,
    );
  }

  /* ---------- Nettoyage ---------- */

  destroy() {
    this.destroyed = true;
    clearTimeout(this.timer);
    this.ro?.disconnect();
    this.io?.disconnect();
    if (this.onVisibility)
      document.removeEventListener('visibilitychange', this.onVisibility);
    this.el.innerHTML = this.originalHTML;
  }
}
