import GlassSurface from './GlassSurface.js';

export default class header {
  constructor(element) {
    this.element = element;
    this.options = {
      threshold: 0,
      show: true,
    };
    this.scrollPosition = 0;
    this.lastScrollPosition = 0;
    this.html = document.documentElement;
    this.navOpenedAt = 0;
    this.init();
    this.initNavMobile();
    this.glass = new GlassSurface(this.element.querySelector('.wrapper'));
  }
  init() {
    this.setOption();
    window.addEventListener('scroll', this.onScroll.bind(this));
  }
  setOption() {
    if ('alwaysShow' in this.element.dataset) {
      this.options.alwaysShow = true;
    }

    if ('threshold' in this.element.dataset) {
      this.options.threshold = parseFloat(this.element.dataset.threshold);
    }
  }
  onScroll() {
    this.lastScrollPosition = this.scrollPosition;
    this.scrollPosition = document.scrollingElement.scrollTop;
    this.setHeaderState();
    this.setDirections();

    // Menu mobile ouvert : si on fait défiler la page, il se referme
    if (
      this.isNavOpen() &&
      Math.abs(this.scrollPosition - this.navOpenedAt) > 60
    ) {
      this.closeNav();
    }
  }
  setHeaderState() {
    if (this.options.alwaysShow == true) {
      this.html.classList.remove('header-is-hidden');
      return;
    }
    if (
      this.scrollPosition >
      document.scrollingElement.scrollHeight * this.options.threshold
    ) {
      this.html.classList.add('header-is-hidden');
    } else {
      this.html.classList.remove('header-is-hidden');
    }
  }
  setDirections() {
    if (this.scrollPosition >= this.lastScrollPosition) {
      this.html.classList.add('is-scrolling-down');
      this.html.classList.remove('is-scrolling-up');
    } else {
      this.html.classList.remove('is-scrolling-down');
      this.html.classList.add('is-scrolling-up');
    }
  }

  /* ---------- Menu mobile ---------- */

  initNavMobile() {
    const toggle = this.element.querySelector('.js-toggle');
    if (!toggle) return;

    this.nav = this.element.querySelector('nav');
    // Toute la zone du hamburger est cliquable (pas seulement le petit icône)
    this.hamburger = toggle.closest('.menu_hamburger') || toggle;

    // Accessibilité : le hamburger se comporte comme un vrai bouton
    this.hamburger.setAttribute('role', 'button');
    this.hamburger.setAttribute('tabindex', '0');
    this.hamburger.setAttribute('aria-label', 'Ouvrir le menu');
    this.hamburger.setAttribute('aria-expanded', 'false');

    this.hamburger.addEventListener('click', this.onToggleNav.bind(this));
    this.hamburger.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        this.onToggleNav();
      }
    });

    // 1. Le menu se referme dès qu'on choisit une option
    this.nav?.addEventListener('click', (e) => {
      if (e.target.closest('a')) this.closeNav();
    });

    // 2. Un tap en dehors du menu le referme
    document.addEventListener('pointerdown', (e) => {
      if (!this.isNavOpen()) return;
      if (this.hamburger.contains(e.target) || this.nav?.contains(e.target))
        return;
      this.closeNav();
    });

    // 3. Échap referme le menu
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && this.isNavOpen()) {
        this.closeNav();
        this.hamburger.focus();
      }
    });

    // 4. Si on passe en affichage ordinateur, le menu se remet à zéro
    window.matchMedia('(max-width: 830px)').addEventListener('change', (e) => {
      if (!e.matches) this.closeNav();
    });
  }
  isNavOpen() {
    return this.html.classList.contains('nav-is-active');
  }
  openNav() {
    this.navOpenedAt = document.scrollingElement.scrollTop;
    this.html.classList.add('nav-is-active');
    this.hamburger?.setAttribute('aria-expanded', 'true');
    this.hamburger?.setAttribute('aria-label', 'Fermer le menu');
  }
  closeNav() {
    this.html.classList.remove('nav-is-active');
    this.hamburger?.setAttribute('aria-expanded', 'false');
    this.hamburger?.setAttribute('aria-label', 'Ouvrir le menu');
  }
  onToggleNav() {
    this.isNavOpen() ? this.closeNav() : this.openNav();
  }
}
